import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Perfil y misión","description":"Reza Bazdar (Godde3s) — ingeniero de software full-stack creativo de Irán. Web, apps, redes, automatización industrial e infraestructura de IA, construidos de punta a punta.","frontmatter":{"title":"Perfil y misión","description":"Reza Bazdar (Godde3s) — ingeniero de software full-stack creativo de Irán. Web, apps, redes, automatización industrial e infraestructura de IA, construidos de punta a punta."},"headers":[],"relativePath":"es/about/profile/index.md","filePath":"es/about/profile/index.md"}`),a={name:`es/about/profile/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="perfil-y-mision" tabindex="-1">Perfil y misión <a class="header-anchor" href="#perfil-y-mision" aria-label="Permalink to “Perfil y misión”">​</a></h1><p>Soy <strong>Reza Bazdar</strong> — en internet me conoce la mayoría como <strong>Godde3s</strong> o <strong>Usf</strong>. Soy un ingeniero de software creativo y versátil de Irán, y construyo cosas de punta a punta: sitios web, aplicaciones, APIs, infraestructura de red, automatización industrial y sistemas de IA. Si corre en una computadora — o en un PLC junto a una línea de producción — puedo construirlo, y probablemente ya lo hice.</p><p>Mi historia no es la ruta clásica de carrera de informática a gran empresa de tecnología. Es la historia de alguien que se negó a aceptar que cualquier sistema sea una caja negra. Paneles proxy, puentes de API, escáneres de puertos, tiendas en línea, lógica ladder — los desarmé todos, los entendí y los reconstruí mejores. Esa curiosidad se convirtió en carrera, y la carrera en una caja de herramientas que cubre todo el stack.</p><h2 id="lo-que-realmente-hago" tabindex="-1">Lo que realmente hago <a class="header-anchor" href="#lo-que-realmente-hago" aria-label="Permalink to “Lo que realmente hago”">​</a></h2><p>La mayoría de los días me encontrarás haciendo una de cuatro cosas: diseñando y lanzando productos web full-stack, construyendo infraestructura de red y anticensura, orquestando agentes de código para que envíen software de producción, o programando controladores industriales. El hilo común es la propiedad — llevo los problemas desde una idea vaga hasta algo de lo que dependen personas reales, y sigo siendo responsable del resultado.</p><table tabindex="0"><thead><tr><th>Área</th><th>Qué significa en la práctica</th></tr></thead><tbody><tr><td>Web y apps full-stack</td><td>React, Vue, Next.js al frente; FastAPI, Gin, Laravel y .NET detrás; bases de datos modeladas y afinadas.</td></tr><tr><td>Redes y proxies</td><td>Túneles VLESS, paneles de suscripción, despliegues de borde en Cloudflare, HF Spaces, Railway, Render, Fly.io y Koyeb.</td></tr><tr><td>IA y codificación agéntica</td><td>Puentes compatibles con OpenAI/Anthropic, routers de modelos y desarrollo diario con OpenCode, Codex, Claude Code y mi stack Hermes.</td></tr><tr><td>Automatización industrial</td><td>Programación PLC en Ladder y Texto Estructurado (IEC 61131-3), diseño HMI y lógica SCADA.</td></tr></tbody></table><h2 id="por-que-creativo-no-es-un-adorno" tabindex="-1">Por qué &quot;creativo&quot; no es un adorno <a class="header-anchor" href="#por-que-creativo-no-es-un-adorno" aria-label="Permalink to “Por qué &quot;creativo&quot; no es un adorno”">​</a></h2><p>Cualquiera puede seguir un tutorial. El trabajo real empieza cuando el tutorial termina — cuando la API no tiene SDK, la red bloquea media internet, el hardware habla un protocolo que nadie documentó y la fecha límite fue ayer. Ahí la creatividad deja de ser un rasgo de personalidad y se convierte en una disciplina de ingeniería: combinar herramientas que nunca debieron funcionar juntas, inventar un plan B cuando el camino principal muere, y entregar de todos modos.</p><div class="tip custom-block"><p class="custom-block-title">La misión</p><p>Construir software genuinamente útil, honesto sobre lo que hace y libre de inspeccionar. Todo lo que lanzo es público en <a href="https://github.com/Godde3s" target="_blank" rel="noreferrer">GitHub</a> — puedes leer cada línea.</p></div><h2 id="numeros-que-me-describen" tabindex="-1">Números que me describen <a class="header-anchor" href="#numeros-que-me-describen" aria-label="Permalink to “Números que me describen”">​</a></h2><ul><li><strong>Más de 9 lenguajes de programación</strong> en producción: Python, JavaScript/TypeScript, Go, PHP, C#, SQL, C/C++, Ladder y Texto Estructurado.</li><li><strong>Más de 30 repositorios públicos</strong> — puentes de API, routers de modelos, paneles proxy, herramientas de seguridad y este mismo portafolio.</li><li><strong>2 idiomas</strong> habla este sitio: English y Español — con la capa i18n lista para crecer.</li><li><strong>1 regla</strong>: cada proyecto debe ejecutarse, no solo compilar.</li></ul><p>Si algo de eso resuena contigo — una idea, un sistema roto, una fecha imposible — mi bandeja está abierta. Las vías más rápidas son Telegram y los datos de contacto al pie de cada página.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};